import{z as B,x as p,o as r,c as i,q as n,j as A,D as E,d as e,s as l,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Raft 成员变更与快照","description":"","frontmatter":{"title":"Raft 成员变更与快照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/raft-membership-snapshot.md","filePath":"cs/raft-membership-snapshot.md","lastUpdated":1791413859000}'),d={name:"cs/raft-membership-snapshot.md"};function m(h,a,f,D,c,u){const s=p("Mermaid");return r(),i("div",null,[a[2]||(a[2]=n('<h1 id="raft-成员变更与快照" tabindex="-1">Raft 成员变更与快照 <a class="header-anchor" href="#raft-成员变更与快照" aria-label="Permalink to &quot;Raft 成员变更与快照&quot;">​</a></h1><div class="epigraph"><p>配置也是日志里的条目。一次只加或减一个节点，新旧多数派重叠。快照截断已提交前缀，安装快照是追赶而不是改历史。</p><footer>—— 据 Ongaro and Ousterhout, USENIX ATC 2014 论文 §4–6 整理</footer></div><p>上一课<a href="/cs/raft">Raft</a>固定成员集合。缺口是<strong>集群要伸缩、日志要截断</strong>：磁盘不能无限长，节点要替换。本课不重写投票规则。后课 Zab 用自己的纪元切配置，对照用，不混协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成员变更若「直接改多数派定义」，会存在一瞬两个不相交多数派同时选出两个主。Raft 论文先给联合共识（新旧配置的多数派都要同意），实现常用<strong>单步变更</strong>：每次日志只加一台或减一台，因为单步时新旧多数派必交。配置在日志中提交之前，领导者同时用新旧计数——细节以论文为准：未提交配置已用于计数，这是实现敏感点。</p><p><span class="marginnote">多数派相交可以代入数字：3 台的多数派要 2 台，4 台的多数派要 3 台，而 \\(2+3=5 \\gt 4\\)，任意两个多数派至少共用 1 台——这台机器保证不会同时把票投给两个主。</span></p><p>快照：把已提交状态写成快照文件，丢弃其前的日志。跟随者落后太多则 InstallSnapshot。快照包含 lastIncludedIndex/term，以接上后面的日志匹配。</p><p><span class="marginnote">单步变更被 etcd 等采用，因为比联合共识少状态。错误实现会出现裂脑配置，Jepsen 测过这类洞。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加节点：先以非投票学习者追日志（工程常见，论文核心是配置条目），再提交「加入」配置。减节点：提交「删除」，被删者停。领导者若发现自己不在新配置中，退位。</p>',10)),(r(),A(o,null,{default:E(()=>[l(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E9%85%8D%E7%BD%AE%E6%9D%A1%E7%9B%AE%E8%BF%9B%E6%97%A5%E5%BF%97%22%5D%20--%3E%20COM%5B%22%E6%8F%90%E4%BA%A4%E8%AF%A5%E6%9D%A1%E7%9B%AE%22%5D%0A%20%20COM%20--%3E%20Q%5B%22%E6%AD%A4%E5%90%8E%E7%94%A8%E6%96%B0%E5%A4%9A%E6%95%B0%E6%B4%BE%22%5D%0A%20%20SNAP%5B%22%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20TRU%5B%22%E6%88%AA%E6%96%AD%E5%89%8D%E7%BC%80%22%5D%0A%20%20SNAP%20--%3E%20IS%5B%22InstallSnapshot%20%E8%BF%BD%E8%B5%B6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("快照必须包含成员配置，否则截断后不知道法定人数。这把配置当成状态机状态的一部分，符合"),t("a",{href:"/cs/replicated-state-machine"},"RSM"),e("。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"安全：单步使任意两次相邻配置的多数派相交，不能并发生成两个主。跳步（一次加两台）破坏该论证。变更过程中可用性可能降：更易凑不齐。",-1)),(r(),A(o,null,{default:E(()=>[l(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20C0%5B%22%E9%85%8D%E7%BD%AE%20A%3A%203%20%E5%8F%B0%20a%2Cb%2Cc%22%5D%20--%3E%20Q1%5B%22A%20%E5%A4%9A%E6%95%B0%E6%B4%BE%3A%202%20%E5%8F%B0%22%5D%0A%20%20ADD%5B%22%E6%97%A5%E5%BF%97%E6%8F%90%E4%BA%A4%E3%80%8E%E5%8A%A0%20d%E3%80%8F%22%5D%20--%3E%20C1%5B%22%E9%85%8D%E7%BD%AE%20B%3A%204%20%E5%8F%B0%20a%2Cb%2Cc%2Cd%22%5D%0A%20%20C0%20--%3E%20ADD%0A%20%20C1%20--%3E%20Q2%5B%22B%20%E5%A4%9A%E6%95%B0%E6%B4%BE%3A%203%20%E5%8F%B0%22%5D%0A%20%20Q1%20--%3E%20OV%5B%22%E4%B8%A4%E5%A4%9A%E6%95%B0%E6%B4%BE%E5%BF%85%E4%BA%A4%3A%202%2B3-4%20%3D%20%E8%87%B3%E5%B0%91%201%20%E5%8F%B0%22%5D%0A%20%20Q2%20--%3E%20OV%0A%20%20JUMP%5B%22%E8%B7%B3%E6%AD%A5%3A%20%E4%B8%80%E6%AC%A1%E5%8A%A0%E4%B8%A4%E5%8F%B0%22%5D%20-.-%3E%20WARN%5B%22%E7%9B%B8%E4%BA%A4%E8%AE%BA%E8%AF%81%E5%A4%B1%E6%95%88%2C%20%E6%9C%89%E8%A3%82%E8%84%91%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">容易以为「改配置」是改一个集群参数、立即生效。Raft 里它是一条日志：必须像普通条目一样被提交，提交之前计数仍按旧配置走；绕过日志人肉改成员文件，等于绕过共识本身。</span></p><p>快照不是 Chandy–Lamport 全局切：它是单对象状态机的前缀压缩。安装快照会丢掉跟随者上与领导者冲突的未提交尾，与 AppendEntries 回退同族。</p><p><span class="marginnote">为什么快照必须带配置与 lastIncludedIndex/term：跟随者从快照恢复后，若不知道自己属于哪个多数派、也接不上后续日志的编号，追赶会静默变成「另一个集群」——错误在很久之后才炸。</span></p><p>本课不写 Kubernetes 滚动升级（后课系统模式）。也不把快照当备份策略全文：备份还要一致切与加密，那是运维。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证联合共识全部不变量，不引入学习者的形式化。后课默认：改 \\(n\\) 必须走日志里的配置条目；截断必须快照带配置与 last term。下一课 ZooKeeper 的 Zab 用事务标识与纪元做类似的事，术语不同。</p><p>配置是数据。把它放在带外「人肉改文件」等于绕过共识。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单步成员变更保持相邻多数派相交。</li><li>配置作为日志条目提交后才切换计数。</li><li>快照压缩已提交前缀；安装是强制对齐。</li><li>出处：Ongaro and Ousterhout, ATC 2014。</li></ul>',9))])}const _=B(d,[["render",m]]);export{b as __pageData,_ as default};
